                    let tl = grid[r1][c1];
                    let tr = grid[r1][c2];
                    let bl = grid[r2][c1];
                    let br = grid[r2][c2];

                    let is_sharp = (tl == '+' || tl == '|') && (tr == '+' || tr == '|') && (bl == '+' || bl == '|') && (br == '+' || br == '|');
                    let is_rounded = tl == '.' && tr == '.' && bl == '\'' && br == '\'';

