                "    <path d=\"M {},{} A {},{} 0,0,1 {},{}\" class=\"nofill\"></path>",
                fmt_num(x_right - 8.0 * settings.scale), fmt_num(y_top),
                fmt_num(8.0 * settings.scale), fmt_num(8.0 * settings.scale),
                fmt_num(x_right), fmt_num(y_top + 8.0 * settings.scale)
            ));
            rect_elements.push(format!(
                "    <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>",
                fmt_num(x_right), fmt_num(y_top + 8.0 * settings.scale),
                fmt_num(x_right), fmt_num(y_bot - 8.0 * settings.scale)
            ));
            rect_elements.push(format!(
                "    <path d=\"M {},{} A {},{} 0,0,0 {},{}\" class=\"nofill\"></path>",
                fmt_num(x_left), fmt_num(y_bot - 4.0 * settings.scale),
                fmt_num(4.0 * settings.scale), fmt_num(4.0 * settings.scale),
