                        let mut top_ok = true;
                        for c in (c1 + 1)..c2 {
                            let ch = grid[r1][c];
                            if ch != '-' && ch != '_' && ch != '+' && ch != '.' {
                                top_ok = false;
                                break;
                            }
                        }
                        let mut bot_ok = true;
                        for c in (c1 + 1)..c2 {
                            let ch = grid[r2][c];
                            if ch != '-' && ch != '_' && ch != '+' && ch != '\'' {
                                bot_ok = false;
                                break;
                            }
                        }
                        let mut left_ok = true;
                        for r in (r1 + 1)..r2 {
                            let ch = grid[r][c1];
                            if ch != '|' && ch != '+' {
                                left_ok = false;
                                break;
                            }
