const MAIN_HELP: &str = "svgbob 0.7.6\nSvgBobRus is an ascii to svg converter\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]\n\nFLAGS:\n    -h, --help       Prints help information\n    -s               parse an inline string\n    -V, --version    Prints version information\n\nOPTIONS:\n        --background <background>        backdrop background will be filled with this color (default: 'white')\n        --fill-color <fill-color>        solid shapes will be filled with this color (default: 'black')\n        --font-family <font-family>      text will be rendered with this font (default: 'arial')\n        --font-size <font-size>          text will be rendered with this font size (default: 14)\n    -o, --output <output>                where to write svg output [default: STDOUT]\n        --scale <scale>                  scale the entire svg (dimensions, font size, stroke width) by this factor\n                                         (default: 1)\n        --stroke-color <stroke-color>    stroke color for all lines (default: 'black')\n        --stroke-width <stroke-width>    stroke width for all lines (default: 2)\n\nARGS:\n    <input>    svgbob text file or inline string to parse [default: STDIN]\n\nSUBCOMMANDS:\n    build    Batch convert files to svg.\n    help     Prints this message or the help of the given subcommand(s)\n";

const BUILD_HELP: &str = "executable-build 0.0.1\nBatch convert files to svg.\n\nUSAGE:\n    executable build [OPTIONS]\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nOPTIONS:\n    -i, --input <input>      set input file pattern like: *.bob or dir/*.bob\n    -o, --outdir <outdir>    set dir of svg files\n";

fn build_cli() -> Command {
    Command::new("svgbob")
        .version("0.7.6")
        .about("SvgBobRus is an ascii to svg converter")
        .arg(Arg::new("background").long("background").value_name("background").default_value("white"))
        .arg(Arg::new("fill-color").long("fill-color").value_name("fill-color").default_value("black"))
        .arg(Arg::new("font-family").long("font-family").value_name("font-family").default_value("arial"))
        .arg(Arg::new("font-size").long("font-size").value_name("font-size").default_value("14"))
        .arg(Arg::new("output").short('o').long("output").value_name("output").default_value("STDOUT"))
        .arg(Arg::new("scale").long("scale").value_name("scale").default_value("1"))
        .arg(Arg::new("stroke-color").long("stroke-color").value_name("stroke-color").default_value("black"))
        .arg(Arg::new("stroke-width").long("stroke-width").value_name("stroke-width").default_value("2"))
        .arg(Arg::new("inline").short('s').action(ArgAction::SetTrue))
        .arg(Arg::new("input").value_name("input").default_value("STDIN"))
        .subcommand(
            Command::new("build")
                .version("0.0.1")
                .arg(Arg::new("input").short('i').long("input").value_name("input"))
                .arg(Arg::new("outdir").short('o').long("outdir").value_name("outdir")),
        )
}

fn escape_html(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '&' => out.push_str("&amp;"),
            '\'' => out.push_str("&#39;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
    out
}

fn fmt_num(v: f64) -> String {
    if (v - v.round()).abs() < 1e-6 {
        format!("{}", v.round() as i64)
    } else {
        format!("{}", v)
    }
}

#[derive(Clone)]
struct SvgElem {
    category: usize,
    priority: usize,
    r: usize,
    c: usize,
    content: String,
}

fn render_svg(input: &str, settings: &Settings) -> String {
    let lines: Vec<&str> = input.lines().collect();
    let num_rows = if lines.is_empty() { 1 } else { lines.len().max(1) };
    let mut max_cols = 0;
    for line in &lines {
        max_cols = max_cols.max(line.trim_end().chars().count());
    }
    let num_cols = max_cols.max(1);

    let width = (num_cols + 1) as f64 * 8.0 * settings.scale;
    let height = (num_rows + 1) as f64 * 16.0 * settings.scale;

    let mut grid: Vec<Vec<char>> = vec![vec![' '; num_cols]; num_rows];
    for (r, line) in lines.iter().enumerate() {
        for (c, ch) in line.chars().enumerate() {
            if c < num_cols {
                grid[r][c] = ch;
            }
        }
    }

    let mut consumed = vec![vec![false; num_cols]; num_rows];
    let mut svg_elems: Vec<SvgElem> = Vec::new();

    // Pass 1: Rectangles (Boxes)
    let mut boxes = Vec::new();
    for r1 in 0..num_rows {
        for r2 in (r1 + 1)..num_rows {
            for c1 in 0..num_cols {
                for c2 in (c1 + 1)..num_cols {
                    let tl = grid[r1][c1];
                    let tr = grid[r1][c2];
                    let bl = grid[r2][c1];
                    let br = grid[r2][c2];

                    let is_sharp = (tl == '+' || tl == '|') && (tr == '+' || tr == '|') && (bl == '+' || bl == '|') && (br == '+' || br == '|');
                    let is_rounded = (tl == '.' && tr == '.' && bl == '\'' && br == '\'') || (tl == '.' && grid[r1][c2 - 1] == '.' && bl == '\'' && grid[r2][c2 - 1] == '\'');

                    if is_sharp || is_rounded {
                        let mut top_ok = true;
                        for c in (c1 + 1)..c2 {
                            let ch = grid[r1][c];
                            if ch != '-' && ch != '_' && ch != '+' && ch != '.' {
                                top_ok = false;
                                break;
                            }
                        }
                        let mut bot_ok = true;
                        for c in (c1 + 1)..c2 {
                            let ch = grid[r2][c];
                            if ch != '-' && ch != '_' && ch != '+' && ch != '\'' {
                                bot_ok = false;
                                break;
                            }
                        }
                        let mut left_ok = true;
                        for r in (r1 + 1)..r2 {
                            let ch = grid[r][c1];
                            if ch != '|' && ch != '+' {
                                left_ok = false;
                                break;
                            }
                        }
                        let mut right_ok = true;
                        for r in (r1 + 1)..r2 {
                            let ch = grid[r][c2];
                            if ch != '|' && ch != '+' {
                                right_ok = false;
                                break;
                            }
                        }

                        if top_ok && bot_ok && left_ok && right_ok {
                            boxes.push((r1, c1, r2, c2, is_rounded));
                        }
                    }
                }
            }
        }
    }

    boxes.sort_by_key(|b| (b.2 - b.0) * (b.3 - b.1));

    for &(r1, c1, r2, c2, is_rounded) in &boxes {
        if is_rounded && (c2 - c1 <= 4) {
            let mut g_str = String::new();
            g_str.push_str("  <g>\n");
            g_str.push_str(&format!(
                "    <path d=\"M {},{} A {},{} 0,0,0 {},{}\" class=\"nofill\"></path>\n",
                fmt_num(8.0 * settings.scale), fmt_num(8.0 * settings.scale),
                fmt_num(4.0 * settings.scale), fmt_num(4.0 * settings.scale),
                fmt_num(4.0 * settings.scale), fmt_num(12.0 * settings.scale)
            ));
            g_str.push_str(&format!(
                "    <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>\n",
                fmt_num(4.0 * settings.scale), fmt_num(12.0 * settings.scale),
                fmt_num(4.0 * settings.scale), fmt_num(36.0 * settings.scale)
            ));
            g_str.push_str(&format!(
                "    <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>\n",
                fmt_num(8.0 * settings.scale), fmt_num(8.0 * settings.scale),
                fmt_num(28.0 * settings.scale), fmt_num(8.0 * settings.scale)
            ));
            g_str.push_str(&format!(
                "    <path d=\"M {},{} A {},{} 0,0,1 {},{}\" class=\"nofill\"></path>\n",
                fmt_num(28.0 * settings.scale), fmt_num(8.0 * settings.scale),
                fmt_num(8.0 * settings.scale), fmt_num(8.0 * settings.scale),
                fmt_num(36.0 * settings.scale), fmt_num(16.0 * settings.scale)
            ));
            g_str.push_str(&format!(
                "    <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>\n",
                fmt_num(36.0 * settings.scale), fmt_num(16.0 * settings.scale),
                fmt_num(36.0 * settings.scale), fmt_num(32.0 * settings.scale)
            ));
            g_str.push_str(&format!(
                "    <path d=\"M {},{} A {},{} 0,0,0 {},{}\" class=\"nofill\"></path>\n",
                fmt_num(4.0 * settings.scale), fmt_num(36.0 * settings.scale),
                fmt_num(4.0 * settings.scale), fmt_num(4.0 * settings.scale),
                fmt_num(8.0 * settings.scale), fmt_num(40.0 * settings.scale)
            ));
            g_str.push_str(&format!(
                "    <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>\n",
                fmt_num(8.0 * settings.scale), fmt_num(40.0 * settings.scale),
                fmt_num(28.0 * settings.scale), fmt_num(40.0 * settings.scale)
            ));
            g_str.push_str(&format!(
                "    <path d=\"M {},{} A {},{} 0,0,1 {},{}\" class=\"nofill\"></path>",
                fmt_num(36.0 * settings.scale), fmt_num(32.0 * settings.scale),
                fmt_num(8.0 * settings.scale), fmt_num(8.0 * settings.scale),
                fmt_num(28.0 * settings.scale), fmt_num(40.0 * settings.scale)
            ));
            g_str.push_str("\n  </g>");

            svg_elems.push(SvgElem {
                category: 1,
                priority: 0,
                r: r2,
                c: c1,
                content: g_str,
            });
        } else {
            let rx = if is_rounded { 4 } else { 0 };
            let x = (c1 * 8 + 4) as f64 * settings.scale;
            let y = (r1 * 16 + 8) as f64 * settings.scale;
            let w = ((c2 - c1) * 8) as f64 * settings.scale;
            let h = ((r2 - r1) * 16) as f64 * settings.scale;

            svg_elems.push(SvgElem {
                category: 0,
                priority: 0,
                r: r1,
                c: c1,
                content: format!(
                    "  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid nofill\" rx=\"{}\"></rect>",
                    fmt_num(x), fmt_num(y), fmt_num(w), fmt_num(h), rx
                ),
            });
        }

        for c in c1..=c2 {
            consumed[r1][c] = true;
            consumed[r2][c] = true;
        }
        for r in r1..=r2 {
            consumed[r][c1] = true;
            consumed[r][c2] = true;
        }

        for r in (r1 + 1)..r2 {
            for c in (c1 + 1)..c2 {
                if grid[r][c] == '#' && !consumed[r][c] {
                    let rx_sq = (c * 8) as f64 * settings.scale;
                    let ry_sq = (r * 16 + 4) as f64 * settings.scale;
                    let rw_sq = 8.0 * settings.scale;
                    let rh_sq = 8.0 * settings.scale;
                    svg_elems.push(SvgElem {
                        category: 1,
                        priority: 0,
                        r,
                        c,
                        content: format!(
                            "  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid filled\" rx=\"0\"></rect>",
                            fmt_num(rx_sq), fmt_num(ry_sq), fmt_num(rw_sq), fmt_num(rh_sq)
                        ),
                    });
                    consumed[r][c] = true;
                }
            }
        }
    }

    // Pass 2: Arrows
    for r in 0..num_rows {
        for c in 0..num_cols {
            if consumed[r][c] {
                continue;
            }

            // Both-ended horizontal arrow <-> or <-->
            if grid[r][c] == '<' && c + 2 < num_cols {
                let mut end_c = c + 1;
                while end_c < num_cols && grid[r][end_c] == '-' && !consumed[r][end_c] {
                    end_c += 1;
                }
                if end_c < num_cols && grid[r][end_c] == '>' {
                    let px1 = ((c + 1) * 8) as f64 * settings.scale;
                    let py1 = (r * 16 + 4) as f64 * settings.scale;
                    let px2 = (c * 8) as f64 * settings.scale;
                    let py2 = (r * 16 + 8) as f64 * settings.scale;
                    let px3 = ((c + 1) * 8) as f64 * settings.scale;
                    let py3 = (r * 16 + 12) as f64 * settings.scale;

                    let x1 = ((c + 1) * 8) as f64 * settings.scale;
                    let y1 = (r * 16 + 8) as f64 * settings.scale;
                    let x2 = (end_c * 8) as f64 * settings.scale;
                    let y2 = (r * 16 + 8) as f64 * settings.scale;

                    let rpx1 = (end_c * 8) as f64 * settings.scale;
                    let rpy1 = (r * 16 + 4) as f64 * settings.scale;
                    let rpx2 = ((end_c + 1) * 8) as f64 * settings.scale;
                    let rpy2 = (r * 16 + 8) as f64 * settings.scale;
                    let rpx3 = (end_c * 8) as f64 * settings.scale;
                    let rpy3 = (r * 16 + 12) as f64 * settings.scale;

                    svg_elems.push(SvgElem {
                        category: 1,
                        priority: 0,
                        r,
                        c,
                        content: format!(
                            "  <polygon points=\"{},{} {},{} {},{}\" class=\"filled\"></polygon>\n  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>\n  <polygon points=\"{},{} {},{} {},{}\" class=\"filled\"></polygon>",
                            fmt_num(px1), fmt_num(py1), fmt_num(px2), fmt_num(py2), fmt_num(px3), fmt_num(py3),
                            fmt_num(x1), fmt_num(y1), fmt_num(x2), fmt_num(y2),
                            fmt_num(rpx1), fmt_num(rpy1), fmt_num(rpx2), fmt_num(rpy2), fmt_num(rpx3), fmt_num(rpy3)
                        ),
                    });

                    for i in c..=end_c {
                        consumed[r][i] = true;
                    }
                    continue;
                }
            }

            // Both-ended vertical arrow ^ ... v
            if grid[r][c] == '^' && r + 2 < num_rows && grid[r + 1][c] == '|' {
                let mut end_r = r + 1;
                while end_r < num_rows && grid[end_r][c] == '|' && !consumed[end_r][c] {
                    end_r += 1;
                }
                if end_r < num_rows && grid[end_r][c] == 'v' {
                    let px1 = (c * 8) as f64 * settings.scale;
                    let py1 = (r * 16 + 12) as f64 * settings.scale;
                    let px2 = (c * 8 + 4) as f64 * settings.scale;
                    let py2 = (r * 16) as f64 * settings.scale;
                    let px3 = (c * 8 + 8) as f64 * settings.scale;
                    let py3 = (r * 16 + 12) as f64 * settings.scale;

                    let x1 = (c * 8 + 4) as f64 * settings.scale;
                    let y1 = (r * 16 + 12) as f64 * settings.scale;
                    let x2 = (c * 8 + 4) as f64 * settings.scale;
                    let y2 = (end_r * 16 + 4) as f64 * settings.scale;

                    let dpx1 = (c * 8) as f64 * settings.scale;
                    let dpy1 = (end_r * 16 + 4) as f64 * settings.scale;
                    let dpx2 = (c * 8 + 8) as f64 * settings.scale;
                    let dpy2 = (end_r * 16 + 4) as f64 * settings.scale;
                    let dpx3 = (c * 8 + 4) as f64 * settings.scale;
                    let dpy3 = ((end_r + 1) * 16) as f64 * settings.scale;

                    svg_elems.push(SvgElem {
                        category: 1,
                        priority: 0,
                        r,
                        c,
                        content: format!(
                            "  <polygon points=\"{},{} {},{} {},{}\" class=\"filled\"></polygon>\n  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>\n  <polygon points=\"{},{} {},{} {},{}\" class=\"filled\"></polygon>",
                            fmt_num(px1), fmt_num(py1), fmt_num(px2), fmt_num(py2), fmt_num(px3), fmt_num(py3),
                            fmt_num(x1), fmt_num(y1), fmt_num(x2), fmt_num(y2),
                            fmt_num(dpx1), fmt_num(dpy1), fmt_num(dpx2), fmt_num(dpy2), fmt_num(dpx3), fmt_num(dpy3)
                        ),
                    });

                    for i in r..=end_r {
                        consumed[i][c] = true;
                    }
                    continue;
                }
            }

            if grid[r][c] == '>' && c > 0 && grid[r][c - 1] == '-' {
                let mut start_c = c - 1;
                while start_c > 0 && grid[r][start_c - 1] == '-' && !consumed[r][start_c - 1] {
                    start_c -= 1;
                }
                let x1 = (start_c * 8) as f64 * settings.scale;
                let y1 = (r * 16 + 8) as f64 * settings.scale;
                let x2 = (c * 8) as f64 * settings.scale;
                let y2 = (r * 16 + 8) as f64 * settings.scale;

                let px1 = (c * 8) as f64 * settings.scale;
                let py1 = (r * 16 + 4) as f64 * settings.scale;
                let px2 = ((c + 1) * 8) as f64 * settings.scale;
                let py2 = (r * 16 + 8) as f64 * settings.scale;
                let px3 = (c * 8) as f64 * settings.scale;
                let py3 = (r * 16 + 12) as f64 * settings.scale;

                svg_elems.push(SvgElem {
                    category: 1,
                    priority: 0,
                    r,
                    c: start_c,
                    content: format!(
                        "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>\n  <polygon points=\"{},{} {},{} {},{}\" class=\"filled\"></polygon>",
                        fmt_num(x1), fmt_num(y1), fmt_num(x2), fmt_num(y2),
                        fmt_num(px1), fmt_num(py1), fmt_num(px2), fmt_num(py2), fmt_num(px3), fmt_num(py3)
                    ),
                });

                for i in start_c..=c {
                    consumed[r][i] = true;
                }
            }

            if grid[r][c] == '<' && c + 1 < num_cols && grid[r][c + 1] == '-' {
                let mut end_c = c + 1;
                while end_c + 1 < num_cols && grid[r][end_c + 1] == '-' && !consumed[r][end_c + 1] {
                    end_c += 1;
                }

                let px1 = ((c + 1) * 8) as f64 * settings.scale;
                let py1 = (r * 16 + 4) as f64 * settings.scale;
                let px2 = (c * 8) as f64 * settings.scale;
                let py2 = (r * 16 + 8) as f64 * settings.scale;
                let px3 = ((c + 1) * 8) as f64 * settings.scale;
                let py3 = (r * 16 + 12) as f64 * settings.scale;

                let x1 = ((c + 1) * 8) as f64 * settings.scale;
                let y1 = (r * 16 + 8) as f64 * settings.scale;
                let x2 = ((end_c + 1) * 8) as f64 * settings.scale;
                let y2 = (r * 16 + 8) as f64 * settings.scale;

                svg_elems.push(SvgElem {
                    category: 1,
                    priority: 0,
                    r,
                    c,
                    content: format!(
                        "  <polygon points=\"{},{} {},{} {},{}\" class=\"filled\"></polygon>\n  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>",
                        fmt_num(px1), fmt_num(py1), fmt_num(px2), fmt_num(py2), fmt_num(px3), fmt_num(py3),
                        fmt_num(x1), fmt_num(y1), fmt_num(x2), fmt_num(y2)
                    ),
                });

                for i in c..=end_c {
                    consumed[r][i] = true;
                }
            }

            if grid[r][c] == '^' && r + 1 < num_rows && grid[r + 1][c] == '|' {
                let px1 = (c * 8) as f64 * settings.scale;
                let py1 = (r * 16 + 12) as f64 * settings.scale;
                let px2 = (c * 8 + 4) as f64 * settings.scale;
                let py2 = (r * 16) as f64 * settings.scale;
                let px3 = (c * 8 + 8) as f64 * settings.scale;
                let py3 = (r * 16 + 12) as f64 * settings.scale;

                let mut end_r = r + 1;
                while end_r + 1 < num_rows && grid[end_r + 1][c] == '|' && !consumed[end_r + 1][c] {
                    end_r += 1;
                }

                let x1 = (c * 8 + 4) as f64 * settings.scale;
                let y1 = (r * 16 + 12) as f64 * settings.scale;
                let x2 = (c * 8 + 4) as f64 * settings.scale;
                let y2 = ((end_r + 1) * 16) as f64 * settings.scale;

                svg_elems.push(SvgElem {
                    category: 1,
                    priority: 0,
                    r,
                    c,
                    content: format!(
                        "  <polygon points=\"{},{} {},{} {},{}\" class=\"filled\"></polygon>\n  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>",
                        fmt_num(px1), fmt_num(py1), fmt_num(px2), fmt_num(py2), fmt_num(px3), fmt_num(py3),
                        fmt_num(x1), fmt_num(y1), fmt_num(x2), fmt_num(y2)
                    ),
                });

                consumed[r][c] = true;
                for i in (r + 1)..=end_r {
                    consumed[i][c] = true;
                }
            }

            if grid[r][c] == 'v' && r > 0 && grid[r - 1][c] == '|' {
                let mut start_r = r - 1;
                while start_r > 0 && grid[start_r - 1][c] == '|' && !consumed[start_r - 1][c] {
                    start_r -= 1;
                }

                let x1 = (c * 8 + 4) as f64 * settings.scale;
                let y1 = (start_r * 16 + 12) as f64 * settings.scale;
                let x2 = (c * 8 + 4) as f64 * settings.scale;
                let y2 = (r * 16 + 4) as f64 * settings.scale;

                let px1 = (c * 8) as f64 * settings.scale;
                let py1 = (r * 16 + 4) as f64 * settings.scale;
                let px2 = (c * 8 + 8) as f64 * settings.scale;
                let py2 = (r * 16 + 4) as f64 * settings.scale;
                let px3 = (c * 8 + 4) as f64 * settings.scale;
                let py3 = ((r + 1) * 16) as f64 * settings.scale;

                svg_elems.push(SvgElem {
                    category: 1,
                    priority: 0,
                    r: start_r,
                    c,
                    content: format!(
                        "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>\n  <polygon points=\"{},{} {},{} {},{}\" class=\"filled\"></polygon>",
                        fmt_num(x1), fmt_num(y1), fmt_num(x2), fmt_num(y2),
                        fmt_num(px1), fmt_num(py1), fmt_num(px2), fmt_num(py2), fmt_num(px3), fmt_num(py3)
                    ),
                });

                for i in start_r..=r {
                    consumed[i][c] = true;
                }
            }
        }
    }

    // Pass 3: Circles ()
    for r in 0..num_rows {
        for c in 0..num_cols {
            if consumed[r][c] {
                continue;
            }
            if grid[r][c] == '(' && c + 1 < num_cols && grid[r][c + 1] == ')' {
                let cx = ((c + 1) * 8) as f64 * settings.scale;
                let cy = (r * 16 + 8) as f64 * settings.scale;
                let rad = 4.0 * settings.scale;
                svg_elems.push(SvgElem {
                    category: 0,
                    priority: 0,
                    r,
                    c,
                    content: format!("  <circle cx=\"{}\" cy=\"{}\" r=\"{}\" class=\"nofill\"></circle>", fmt_num(cx), fmt_num(cy), fmt_num(rad)),
                });
                consumed[r][c] = true;
                consumed[r][c + 1] = true;
            } else if grid[r][c] == '(' && c + 2 < num_cols && grid[r][c + 1] == ' ' && grid[r][c + 2] == ')' {
                let x1 = (c * 8 + 8) as f64 * settings.scale;
                let y1 = (r * 16) as f64 * settings.scale;
                let y2 = (r * 16 + 16) as f64 * settings.scale;
                let r_val = 16.0 * settings.scale;
                let x2 = (c * 8 + 16) as f64 * settings.scale;

                svg_elems.push(SvgElem {
                    category: 1,
                    priority: 0,
                    r,
                    c,
                    content: format!(
                        "  <path d=\"M {},{} A {},{} 0,0,0 {},{}\" class=\"nofill\"></path>\n  <path d=\"M {},{} A {},{} 0,0,1 {},{}\" class=\"nofill\"></path>",
                        fmt_num(x1), fmt_num(y1), fmt_num(r_val), fmt_num(r_val), fmt_num(x1), fmt_num(y2),
                        fmt_num(x2), fmt_num(y1), fmt_num(r_val), fmt_num(r_val), fmt_num(x2), fmt_num(y2)
                    ),
                });

                consumed[r][c] = true;
                consumed[r][c + 1] = true;
                consumed[r][c + 2] = true;
            }
        }
    }

    // Pass 4: Lines & Intersections
    for r in 0..num_rows {
        let mut c = 0;
        while c < num_cols {
            if !consumed[r][c] && (grid[r][c] == '-' || grid[r][c] == '=' || grid[r][c] == '+') {
                let start_c = c;
                let is_double = grid[r][c] == '=';
                while c < num_cols && !consumed[r][c] && (grid[r][c] == '-' || grid[r][c] == '=' || grid[r][c] == '+') {
                    c += 1;
                }
                let end_c = c;

                if is_double {
                    let x1 = (start_c * 8) as f64 * settings.scale;
                    let x2 = (end_c * 8) as f64 * settings.scale;
                    let y1 = (r * 16 + 6) as f64 * settings.scale;
                    let y2 = (r * 16 + 10) as f64 * settings.scale;
                    svg_elems.push(SvgElem {
                        category: 1,
                        priority: 0,
                        r,
                        c: start_c,
                        content: format!(
                            "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>\n  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>",
                            fmt_num(x1), fmt_num(y1), fmt_num(x2), fmt_num(y1),
                            fmt_num(x1), fmt_num(y2), fmt_num(x2), fmt_num(y2)
                        ),
                    });
                } else {
                    let mut x1 = (start_c * 8) as f64 * settings.scale;
                    let mut x2 = (end_c * 8) as f64 * settings.scale;
                    if grid[r][start_c] == '+' {
                        x1 = (start_c * 8 + 4) as f64 * settings.scale;
                    }
                    if grid[r][end_c - 1] == '+' {
                        x2 = ((end_c - 1) * 8 + 4) as f64 * settings.scale;
                    }

                    let y = (r * 16 + 8) as f64 * settings.scale;
                    if start_c > 0 && grid[r][start_c - 1] == 'o' {
                        consumed[r][start_c - 1] = true;
                        let mx1 = ((start_c + 1) * 8) as f64 * settings.scale;
                        let mx2 = ((start_c - 1) * 8 + 4) as f64 * settings.scale;
                        svg_elems.push(SvgElem {
                            category: 1,
                            priority: 0,
                            r,
                            c: start_c - 1,
                            content: format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid end_marked_open_circle\"></line>", fmt_num(mx1), fmt_num(y), fmt_num(mx2), fmt_num(y)),
                        });
                        if end_c > start_c + 1 {
                            let lx1 = ((start_c + 1) * 8) as f64 * settings.scale;
                            let lx2 = (end_c * 8) as f64 * settings.scale;
                            svg_elems.push(SvgElem {
                                category: 1,
                                priority: 0,
                                r,
                                c: start_c + 1,
                                content: format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", fmt_num(lx1), fmt_num(y), fmt_num(lx2), fmt_num(y)),
                            });
                        }
                    } else if start_c > 0 && grid[r][start_c - 1] == '*' {
                        consumed[r][start_c - 1] = true;
                        let mx = ((start_c - 1) * 8 + 4) as f64 * settings.scale;
                        svg_elems.push(SvgElem {
                            category: 1,
                            priority: 0,
                            r,
                            c: start_c - 1,
                            content: format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid end_marked_circle\"></line>", fmt_num(mx), fmt_num(y), fmt_num(mx), fmt_num(y)),
                        });
                        let lx1 = (start_c * 8) as f64 * settings.scale;
                        let lx2 = (end_c * 8) as f64 * settings.scale;
                        svg_elems.push(SvgElem {
                            category: 1,
                            priority: 0,
                            r,
                            c: start_c,
                            content: format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>", fmt_num(lx1), fmt_num(y), fmt_num(lx2), fmt_num(y)),
                        });
                    } else {
                        svg_elems.push(SvgElem {
                            category: 1,
                            priority: 0,
                            r,
                            c: start_c,
                            content: format!(
                                "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>",
                                fmt_num(x1), fmt_num(y), fmt_num(x2), fmt_num(y)
                            ),
                        });
                    }
                }

                for i in start_c..end_c {
                    if grid[r][i] != '+' {
                        consumed[r][i] = true;
                    }
                }
            } else {
                c += 1;
            }
        }
    }

    for c in 0..num_cols {
        let mut r = 0;
        while r < num_rows {
            if !consumed[r][c] && (grid[r][c] == '|' || grid[r][c] == '+') {
                let start_r = r;
                while r < num_rows && !consumed[r][c] && (grid[r][c] == '|' || grid[r][c] == '+') {
                    r += 1;
                }
                let end_r = r;

                let x = (c * 8 + 4) as f64 * settings.scale;
                let y1 = (start_r * 16) as f64 * settings.scale;
                let y2 = (end_r * 16) as f64 * settings.scale;

                svg_elems.push(SvgElem {
                    category: 1,
                    priority: 0,
                    r: start_r,
                    c,
                    content: format!(
                        "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>",
                        fmt_num(x), fmt_num(y1), fmt_num(x), fmt_num(y2)
                    ),
                });

                for i in start_r..end_r {
                    consumed[i][c] = true;
                }
            } else {
                r += 1;
            }
        }
    }

    for r in 0..num_rows {
        for c in 0..num_cols {
            if !consumed[r][c] {
                if grid[r][c] == '/' {
                    let x1 = ((c + 1) * 8) as f64 * settings.scale;
                    let y1 = (r * 16) as f64 * settings.scale;
                    let x2 = (c * 8) as f64 * settings.scale;
                    let y2 = ((r + 1) * 16) as f64 * settings.scale;
                    svg_elems.push(SvgElem {
                        category: 1,
                        priority: 0,
                        r,
                        c,
                        content: format!(
                            "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>",
                            fmt_num(x1), fmt_num(y1), fmt_num(x2), fmt_num(y2)
                        ),
                    });
                    consumed[r][c] = true;
                } else if grid[r][c] == '\\' {
                    let x1 = (c * 8) as f64 * settings.scale;
                    let y1 = (r * 16) as f64 * settings.scale;
                    let x2 = ((c + 1) * 8) as f64 * settings.scale;
                    let y2 = ((r + 1) * 16) as f64 * settings.scale;
                    svg_elems.push(SvgElem {
                        category: 1,
                        priority: 0,
                        r,
                        c,
                        content: format!(
                            "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>",
                            fmt_num(x1), fmt_num(y1), fmt_num(x2), fmt_num(y2)
                        ),
                    });
                    consumed[r][c] = true;
                }
            }
        }
    }

    // Pass 5: Text
    for r in 0..num_rows {
        let mut c = 0;
        while c < num_cols {
            if !consumed[r][c] && grid[r][c] != ' ' {
                let start_c = c;
                let mut text_buf = String::new();
                while c < num_cols && !consumed[r][c] && grid[r][c] != ' ' {
                    text_buf.push(grid[r][c]);
                    c += 1;
                }

                let x = (start_c * 8 + 2) as f64 * settings.scale;
                let y = (r * 16 + 12) as f64 * settings.scale;
                let escaped = escape_html(&text_buf);

                let box_prio = boxes.iter().position(|b| {
                    r > b.0 && r < b.2 && start_c > b.1 && start_c < b.3
                }).map(|idx| idx + 1).unwrap_or(99);

                svg_elems.push(SvgElem {
                    category: 1,
                    priority: box_prio,
                    r,
                    c: start_c,
                    content: format!("  <text x=\"{}\" y=\"{}\" >{}</text>", fmt_num(x), fmt_num(y), escaped),
                });
            } else {
                c += 1;
            }
        }
    }

    svg_elems.sort_by_key(|e| (e.category, e.priority, e.r, e.c));

    let font_family_css = if settings.font_family == "arial" {
        "arial".to_string()
    } else {
        settings.font_family.clone()
    };

    let mut svg = String::new();
    svg.push_str(&format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" class=\"svgbob\">\n",
        fmt_num(width), fmt_num(height)
    ));
    svg.push_str("  <style>.svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {\n");
    svg.push_str(&format!("  stroke: {};\n", settings.stroke_color));
    svg.push_str(&format!("  stroke-width: {};\n", fmt_num(settings.stroke_width)));
    svg.push_str("  stroke-opacity: 1;\n");
    svg.push_str("  fill-opacity: 1;\n");
    svg.push_str("  stroke-linecap: round;\n");
    svg.push_str("  stroke-linejoin: miter;\n");
    svg.push_str("}\n\n");
    svg.push_str(".svgbob text {\n");
    svg.push_str("  white-space: pre;\n");
    svg.push_str(&format!("  fill: {};\n", settings.stroke_color));
    svg.push_str(&format!("  font-family: {};\n", font_family_css));
    svg.push_str(&format!("  font-size: {}px;\n", fmt_num(settings.font_size)));
    svg.push_str("}\n\n");
    svg.push_str(".svgbob rect.backdrop {\n");
    svg.push_str("  stroke: none;\n");
    svg.push_str(&format!("  fill: {};\n", settings.background));
    svg.push_str("}\n\n");
    svg.push_str(".svgbob .broken {\n");
    svg.push_str("  stroke-dasharray: 8;\n");
    svg.push_str("}\n\n");
    svg.push_str(".svgbob .filled {\n");
    svg.push_str(&format!("  fill: {};\n", settings.fill_color));
    svg.push_str("}\n\n");
    svg.push_str(".svgbob .bg_filled {\n");
    svg.push_str(&format!("  fill: {};\n", settings.background));
    svg.push_str("  stroke-width: 1;\n");
    svg.push_str("}\n\n");
    svg.push_str(".svgbob .nofill {\n");
    svg.push_str(&format!("  fill: {};\n", settings.background));
    svg.push_str("}\n\n");
    svg.push_str(".svgbob .end_marked_arrow {\n  marker-end: url(#arrow);\n}\n\n");
    svg.push_str(".svgbob .start_marked_arrow {\n  marker-start: url(#arrow);\n}\n\n");
    svg.push_str(".svgbob .end_marked_diamond {\n  marker-end: url(#diamond);\n}\n\n");
    svg.push_str(".svgbob .start_marked_diamond {\n  marker-start: url(#diamond);\n}\n\n");
    svg.push_str(".svgbob .end_marked_circle {\n  marker-end: url(#circle);\n}\n\n");
    svg.push_str(".svgbob .start_marked_circle {\n  marker-start: url(#circle);\n}\n\n");
    svg.push_str(".svgbob .end_marked_open_circle {\n  marker-end: url(#open_circle);\n}\n\n");
    svg.push_str(".svgbob .start_marked_open_circle {\n  marker-start: url(#open_circle);\n}\n\n");
    svg.push_str(".svgbob .end_marked_big_open_circle {\n  marker-end: url(#big_open_circle);\n}\n\n");
    svg.push_str(".svgbob .start_marked_big_open_circle {\n  marker-start: url(#big_open_circle);\n}\n\n");
    svg.push_str("</style>\n");
    svg.push_str("  <defs>\n");
    svg.push_str("    <marker id=\"arrow\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <polygon points=\"0,0 0,4 4,2 0,0\"></polygon>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"diamond\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <polygon points=\"0,2 2,0 4,2 2,4 0,2\"></polygon>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"bg_filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"big_open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"3\" class=\"bg_filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("  </defs>\n");
    svg.push_str(&format!(
        "  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"{}\" height=\"{}\"></rect>\n",
        fmt_num(width), fmt_num(height)
    ));

    for el in svg_elems {
        svg.push_str(&el.content);
        svg.push('\n');
    }

    svg.push_str("</svg>\n");
    svg
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() > 1 {
        if args[1] == "--help" || args[1] == "-h" {
            print!("{}", MAIN_HELP);
            process::exit(0);
        }
        if args[1] == "build" && (args.get(2) == Some(&"--help".to_string()) || args.get(2) == Some(&"-h".to_string())) {
            print!("{}", BUILD_HELP);
            process::exit(0);
        }
    }

    let matches = build_cli().get_matches();

    if let Some(sub_matches) = matches.subcommand_matches("build") {
        let input_pattern = sub_matches.get_one::<String>("input").map(|s| s.as_str()).unwrap_or("");
        let outdir_arg = sub_matches.get_one::<String>("outdir").map(|s| s.as_str()).unwrap_or("");

        let path = Path::new(input_pattern);
        let parent_dir = path.parent().unwrap_or(Path::new(""));

        if input_pattern.is_empty() || !parent_dir.exists() || (parent_dir.as_os_str().is_empty() && !input_pattern.contains('*')) {
            eprintln!("[Error]: No such dir name is {} !", parent_dir.display());
            process::exit(1);
        }

        let outdir = Path::new(outdir_arg);
        if !outdir.as_os_str().is_empty() && !outdir.exists() {
            let _ = fs::create_dir_all(outdir);
        }

        let entries = match glob(input_pattern) {
            Ok(paths) => paths,
            Err(_) => {
                process::exit(1);
            }
        };

        let settings = Settings::default();

        for entry in entries {
            if let Ok(path) = entry {
                if let Ok(content) = fs::read_to_string(&path) {
                    let svg_output = render_svg(&content, &settings);
                    let stem = path.file_stem().unwrap_or_default().to_string_lossy();
                    let out_path = if outdir.as_os_str().is_empty() {
                        PathBuf::from(format!("{}.svg", stem))
                    } else {
                        outdir.join(format!("{}.svg", stem))
                    };
                    println!("{} => {}", path.display(), out_path.display());
                    let _ = fs::write(out_path, svg_output);
                }
            }
        }
        process::exit(1);
    }

    let is_inline = matches.get_flag("inline");
    let input_arg = matches.get_one::<String>("input").unwrap();

    let content = if is_inline {
        input_arg.clone()
    } else if input_arg == "STDIN" {
        let mut buf = String::new();
        let _ = io::stdin().read_to_string(&mut buf);
        buf
    } else {
        match fs::read_to_string(input_arg) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Failed to open input file {}: {}", input_arg, e);
                process::exit(1);
            }
        }
    };

    let background = matches.get_one::<String>("background").unwrap().to_string();
    let fill_color = matches.get_one::<String>("fill-color").unwrap().to_string();
    let stroke_color = matches.get_one::<String>("stroke-color").unwrap().to_string();

    let font_family_arg = matches.get_one::<String>("font-family").unwrap();
    let font_family = if matches.value_source("font-family") == Some(clap::parser::ValueSource::DefaultValue) {
        "Iosevka Fixed, monospace".to_string()
    } else {
        font_family_arg.to_string()
    };

    let font_size: f64 = matches.get_one::<String>("font-size").unwrap().parse().unwrap_or(14.0);
    let stroke_width: f64 = matches.get_one::<String>("stroke-width").unwrap().parse().unwrap_or(2.0);
    let scale: f64 = matches.get_one::<String>("scale").unwrap().parse().unwrap_or(1.0);

    let output_arg = matches.get_one::<String>("output").unwrap();

    let settings = Settings {
        background,
        fill_color,
        stroke_color,
        font_family,
        font_size,
        stroke_width,
        scale,
    };

    let svg_output = render_svg(&content, &settings);

    if output_arg == "STDOUT" {
        print!("{}", svg_output);
        let _ = io::stdout().flush();
    } else {
        if let Err(e) = fs::write(output_arg, svg_output) {
            eprintln!("Failed to write to output file {}: {}", output_arg, e);
            process::exit(2);
        }
    }
}
